(3713536, 524008, 62787, '<td valign="top">:) Effective social commentary. 7</td>', ':) Effective social commentary. 7', '2007-05-30 09:30:52.000000', NULL, 1),
(3713537, 520701, 62787, '<td valign="top">Blurry, oversharpened, subject patter unclear, distracting background.</td>', 'Blurry, oversharpened, subject patter unclear, distracting background.', '2007-05-30 09:31:27.000000', NULL, 1),
