(3713540, 519119, 46415, '<td valign="top">poor photo</td>', 'poor photo', '2007-05-30 09:31:59.000000', NULL, 1),
(3713542, 523793, 62787, '<td valign="top">Nice picture, nice composition. Nude shots would have been more in keeping with the subject matter though :p</td>', 'Nice picture, nice composition. Nude shots would have been more in keeping with the subject matter though :p', '2007-05-30 09:32:33.000000', NULL, 1),
(3713543, 524109, 46415, '<td valign="top">very arresting photo.</td>', 'very arresting photo.', '2007-05-30 09:32:43.000000', NULL, 1),
