(3713550, 523842, 62787, '<td valign="top">Not very convincingly staged. A different model position and a differently composed shot would have done better.</td>', 'Not very convincingly staged. A different model position and a differently composed shot would have done better.', '2007-05-30 09:34:41.000000', NULL, 1),
(3713551, 522977, 46415, '<td valign="top">nice colors.</td>', 'nice colors.', '2007-05-30 09:34:58.000000', NULL, 1),
