(3713558, 522490, 62787, '<td valign="top">The highlights from the light are blown out, and the tree is in the way. It''s not a bad shot, but it''s competing with lots of other similar ones, it needs to be perfect to do well here.</td>', 'The highlights from the light are blown out, and the tree is in the way. It''s not a bad shot, but it''s competing with lots of other similar ones, it needs to be perfect to do well here.', '2007-05-30 09:36:19.000000', NULL, 1),
(3713565, 522076, 62787, '<td valign="top">:) kinda cute. The lighting could''ve been better (her face should be lit up more), you cut off the top of the wing, and maybe a slightly different angle would''ve worked better. I''m impressed with the staged clouds though!</td>', ':) kinda cute. The lighting could''ve been better (her face should be lit up more), you cut off the top of the wing, and maybe a slightly different angle would''ve worked better. I''m impressed with the staged clouds though!', '2007-05-30 09:38:26.000000', NULL, 1),
(3713572, 523419, 62787, '<td valign="top">Heh, my thoughts exactly. 7</td>', 'Heh, my thoughts exactly. 7', '2007-05-30 09:39:18.000000', NULL, 1),
(3713575, 523915, 62787, '<td valign="top">Ooh, good dramatic shot. Very emotive. 8</td>', 'Ooh, good dramatic shot. Very emotive. 8', '2007-05-30 09:40:18.000000', NULL, 1),
(3713583, 519549, 62787, '<td valign="top">Decent idea, but could have been better executed. The lighting isn''t great, it''s quite hard to tell what''s going on in the shot.</td>', 'Decent idea, but could have been better executed. The lighting isn''t great, it''s quite hard to tell what''s going on in the shot.', '2007-05-30 09:42:19.000000', NULL, 1),
(3713586, 523326, 70875, '<td valign="top">I like the light &amp; color in this. Nice concept also, 8.</td>', 'I like the light & color in this. Nice concept also, 8.', '2007-05-30 09:42:55.000000', NULL, 1),
(3713588, 521828, 62787, '<td valign="top">The incence makes it stand out from the other numerous buddha shots, and the composition works very well. I think this is the first Buddha I''ve come across in the challenge that I actually like.</td>', 'The incence makes it stand out from the other numerous buddha shots, and the composition works very well. I think this is the first Buddha I''ve come across in the challenge that I actually like.', '2007-05-30 09:43:24.000000', NULL, 1),
(3713594, 520944, 62787, '<td valign="top">Nice composition and interesting light, but I''m guessing it''ll get voted down because the star doesn''t seem in focus enough.</td>', 'Nice composition and interesting light, but I''m guessing it''ll get voted down because the star doesn''t seem in focus enough.', '2007-05-30 09:44:19.000000', NULL, 1),
(3713596, 523543, 62787, '<td valign="top">Good idea, but it would help to make the silhouette more obvious in some way.</td>', 'Good idea, but it would help to make the silhouette more obvious in some way.', '2007-05-30 09:44:52.000000', NULL, 1),
(3713597, 523128, 62787, '<td valign="top">Great light capture.</td>', 'Great light capture.', '2007-05-30 09:45:18.000000', NULL, 1),
(3713600, 523517, 62787, '<td valign="top">Nice, but oversharpened.</td>', 'Nice, but oversharpened.', '2007-05-30 09:45:37.000000', NULL, 1),
(3713602, 521511, 70875, '<td valign="top">This is making me dizzy... very clear though, 7.</td>', 'This is making me dizzy... very clear though, 7.', '2007-05-30 09:45:55.000000', NULL, 1),
(3713603, 521274, 62787, '<td valign="top">Has a lot of potential, but doesn''t seem to be in focus enough.</td>', 'Has a lot of potential, but doesn''t seem to be in focus enough.', '2007-05-30 09:46:12.000000', NULL, 1),
(3713606, 523064, 62787, '<td valign="top">Very nice angle. The curves of the archway work very well, and it looks nice in B&amp;W.</td>', 'Very nice angle. The curves of the archway work very well, and it looks nice in B&W.', '2007-05-30 09:47:02.000000', NULL, 1);
