(3713608, 523897, 62787, '<td valign="top">Very dramatic. A tad oversharpened, and it''s a shame that the statue itself isn''t slightly more lit up (possibly fixable in post processing)</td>', 'Very dramatic. A tad oversharpened, and it''s a shame that the statue itself isn''t slightly more lit up (possibly fixable in post processing)', '2007-05-30 09:47:53.000000', NULL, 1),
(3713613, 524215, 62787, '<td valign="top">Bad light, oversharpened to the extent of being painful to look at, and I have no idea what''s happening with the top of the book.</td>', 'Bad light, oversharpened to the extent of being painful to look at, and I have no idea what''s happening with the top of the book.', '2007-05-30 09:49:01.000000', NULL, 1),
(3713618, 523466, 62787, '<td valign="top">Meets the challenge, but looks like an ordinary snapshot.</td>', 'Meets the challenge, but looks like an ordinary snapshot.', '2007-05-30 09:49:32.000000', NULL, 1),
