(3719548, 523838, 78062, '<td valign="top">Nice shot but I think the pillar thingy needs to be a bit lighter at the top, it gets gradually darker as you go up which distracts me from it.</td>', 'Nice shot but I think the pillar thingy needs to be a bit lighter at the top, it gets gradually darker as you go up which distracts me from it.', '2007-05-31 15:04:42.000000', NULL, 1),
(3719553, 520497, 78062, '<td valign="top">Nice idea but something about it doesn''t float my boat.</td>', 'Nice idea but something about it doesn''t float my boat.', '2007-05-31 15:05:13.000000', NULL, 1),
(3719554, 524089, 78062, '<td valign="top">Jesus and... garlic?</td>', 'Jesus and... garlic?', '2007-05-31 15:05:27.000000', NULL, 1),
