(3721081, 520476, 77196, '<td valign="top">If this was meant to communicate defiance and not repentance, it succeeds.</td>', 'If this was meant to communicate defiance and not repentance, it succeeds.', '2007-05-31 22:53:44.000000', NULL, 1),
