(3721100, 523827, 77196, '<td valign="top">Nice shot, but not enough lighting on the subject.</td>', 'Nice shot, but not enough lighting on the subject.', '2007-05-31 22:58:30.000000', NULL, 1),
(3721114, 523915, 77196, '<td valign="top">The monochrome, combined with excellent highlights and contrast makes this an exceptional shot. For example, the white highlight on the near edge of the hammer saves that part of the shot from being too dark. The dirty hands on the hammer and nail vs. the clean hand. Even the wood of the cross looks metallic in this lighting.</td>', 'The monochrome, combined with excellent highlights and contrast makes this an exceptional shot. For example, the white highlight on the near edge of the hammer saves that part of the shot from being too dark. The dirty hands on the hammer and nail vs. the clean hand. Even the wood of the cross looks metallic in this lighting.', '2007-05-31 23:02:07.000000', NULL, 1),
(3721117, 523482, 64928, '<td valign="top">It would be be even better if you had the Bible open to Matthew 7:12 or Luke 6:31.</td>', 'It would be be even better if you had the Bible open to Matthew 7:12 or Luke 6:31.', '2007-05-31 23:02:35.000000', NULL, 1),
(3721119, 523128, 64928, '<td valign="top">Beautiful lighting!</td>', 'Beautiful lighting!', '2007-05-31 23:03:23.000000', NULL, 1),
(3721125, 523487, 43400, '<td valign="top">I truly like this, it tells a story and very artistic. I would have rotated the image slightly clockwise. The person in motion really makes this work--9</td>', 'I truly like this, it tells a story and very artistic. I would have rotated the image slightly clockwise. The person in motion really makes this work--9', '2007-05-31 23:03:54.000000', NULL, 1),
(3721128, 523701, 64928, '<td valign="top">interesting perspective</td>', 'interesting perspective', '2007-05-31 23:05:02.000000', NULL, 1),
(3721130, 523326, 77196, '<td valign="top">Using the crease between pages allows you to get some nice interesting shadows.</td>', 'Using the crease between pages allows you to get some nice interesting shadows.', '2007-05-31 23:05:21.000000', NULL, 1),
(3721138, 523175, 62187, '<td valign="top">If I were voting in this challenge, I''d give you a 10 - purely for the laugh I needed! Amen - };&gt;)</td>', 'If I were voting in this challenge, I''d give you a 10 - purely for the laugh I needed! Amen - };>)', '2007-05-31 23:06:44.000000', NULL, 1),
(3721139, 522884, 43400, '<td valign="top">nice blur effects and image and has a surreal appeal to it. though I see this as being more ''spiritual'' than ''religious''.-7</td>', 'nice blur effects and image and has a surreal appeal to it. though I see this as being more ''spiritual'' than ''religious''.-7', '2007-05-31 23:06:49.000000', NULL, 1),
(3721140, 524047, 77196, '<td valign="top">The rocks in the background appear to be a little washed out. Love the bright red rock and contrasting chapel. (I know, I wouldn''t have been able to resist the tower rocks or clouds either...)</td>', 'The rocks in the background appear to be a little washed out. Love the bright red rock and contrasting chapel. (I know, I wouldn''t have been able to resist the tower rocks or clouds either...)', '2007-05-31 23:06:52.000000', NULL, 1),
(3721144, 523838, 77196, '<td valign="top">Awesome sky, and the marble almost looks like a lightning bolt!</td>', 'Awesome sky, and the marble almost looks like a lightning bolt!', '2007-05-31 23:07:38.000000', NULL, 1),
