(3721448, 523180, 77196, '<td valign="top">This is a tough shot. Model''s hair covers Mustang.</td>', 'This is a tough shot. Model''s hair covers Mustang.', '2007-06-01 00:15:26.000000', NULL, 1),
(3721456, 521937, 72833, '<td valign="top">His love for us is amazing. How could someone bear that pain.. for wretches like us? This image is mighty powerful. It helps us to see what the life he lived on earth was for. 10, because it is a great image, but even more than that, this definately will touch people. Thank you for this, and God Bless you.</td>', 'His love for us is amazing. How could someone bear that pain.. for wretches like us? This image is mighty powerful. It helps us to see what the life he lived on earth was for. 10, because it is a great image, but even more than that, this definately will touch people. Thank you for this, and God Bless you.', '2007-06-01 00:17:33.000000', NULL, 1),
(3721482, 523259, 72833, '<td valign="top">I''m sorry to hear that. Maybe a relationship with Jesus could fix it</td>', 'I''m sorry to hear that. Maybe a relationship with Jesus could fix it', '2007-06-01 00:26:27.000000', NULL, 1),
(3721517, 521326, 79271, '<td valign="top">awesome editing</td>', 'awesome editing', '2007-06-01 00:38:24.000000', NULL, 1),
(3721525, 523704, 24022, '<td valign="top">Very original</td>', 'Very original', '2007-06-01 00:42:20.000000', NULL, 1),
(3721591, 523787, 67697, '<td valign="top">Poor Almighty does not have many followers hehe.  Very creative perspective!</td>', 'Poor Almighty does not have many followers hehe.  Very creative perspective!', '2007-06-01 00:55:51.000000', NULL, 1),
(3721598, 524082, 67697, '<td valign="top">Nice use of light.  A peaceful pic...</td>', 'Nice use of light.  A peaceful pic...', '2007-06-01 00:57:02.000000', NULL, 1),
(3721606, 523610, 67697, '<td valign="top">Quite a capture - really grabs you.  Not sure I''d want to enter that building lol.  Great use of black and white contrasts.</td>', 'Quite a capture - really grabs you.  Not sure I''d want to enter that building lol.  Great use of black and white contrasts.', '2007-06-01 00:58:05.000000', NULL, 1),
(3721613, 524050, 67697, '<td valign="top">I think this photo would have held on it''s own without the tear.  The lighting is good and so are the contrasts.</td>', 'I think this photo would have held on it''s own without the tear.  The lighting is good and so are the contrasts.', '2007-06-01 00:59:31.000000', NULL, 1),
(3721644, 523629, 67697, '<td valign="top">Without a title this would not ring out religion to me.  But I like the composition of the pic (and the gorgeous blue water!) so I am giving a 6.</td>', 'Without a title this would not ring out religion to me.  But I like the composition of the pic (and the gorgeous blue water!) so I am giving a 6.', '2007-06-01 01:05:47.000000', NULL, 1),
(3721651, 523396, 67697, '<td valign="top">Funny!</td>', 'Funny!', '2007-06-01 01:06:11.000000', NULL, 1),
(3721657, 519476, 67697, '<td valign="top">I agree with this philosophy.  God gave me three beautiful angels as well.</td>', 'I agree with this philosophy.  God gave me three beautiful angels as well.', '2007-06-01 01:07:00.000000', NULL, 1),
(3721659, 521496, 67697, '<td valign="top">Nice capture of the fog.</td>', 'Nice capture of the fog.', '2007-06-01 01:07:29.000000', NULL, 1),
(3721665, 521937, 67697, '<td valign="top">Very gorgeous.  The sky is an amazing enhancement to the pic.  Love the silhouette.</td>', 'Very gorgeous.  The sky is an amazing enhancement to the pic.  Love the silhouette.', '2007-06-01 01:07:58.000000', NULL, 1),
(3721911, 523523, 22734, '<td valign="top">A very contemplative rendtiton. Personally I would have made the white even thinner and then just off white to preserve its solemn feel. Very nice work. Bump.</td>', 'A very contemplative rendtiton. Personally I would have made the white even thinner and then just off white to preserve its solemn feel. Very nice work. Bump.', '2007-06-01 01:46:40.000000', NULL, 1),
(3721915, 523654, 22734, '<td valign="top">Like the definete long stroke of the stride and the charming background teatment. Bump.</td>', 'Like the definete long stroke of the stride and the charming background teatment. Bump.', '2007-06-01 01:47:32.000000', NULL, 1),
(3722048, 523175, 79276, '<td valign="top">Great shock value</td>', 'Great shock value', '2007-06-01 02:08:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3722054, 520878, 79276, '<td valign="top">Waiting for Him to answer your prayer?  Nice definition.</td>', 'Waiting for Him to answer your prayer?  Nice definition.', '2007-06-01 02:09:39.000000', NULL, 1),
(3722061, 521194, 79276, '<td valign="top">Dead men don''t bleed...</td>', 'Dead men don''t bleed...', '2007-06-01 02:10:44.000000', NULL, 1),
(3722080, 523817, 79276, '<td valign="top">Nice aspect and lighting.  Makes me want to hear some Danny Elfman on this instrument.</td>', 'Nice aspect and lighting.  Makes me want to hear some Danny Elfman on this instrument.', '2007-06-01 02:14:38.000000', NULL, 1),
(3722096, 523236, 79276, '<td valign="top">Lucky shadow catch.  It turns the cross upside down, to parody the imaginary struggle between "god" and "devil", or our interpretation of good and evil.  It almost looks surreal, too.</td>', 'Lucky shadow catch.  It turns the cross upside down, to parody the imaginary struggle between "god" and "devil", or our interpretation of good and evil.  It almost looks surreal, too.', '2007-06-01 02:16:33.000000', NULL, 1),
(3722101, 523668, 79276, '<td valign="top">Jiggle me Jeebus!</td>', 'Jiggle me Jeebus!', '2007-06-01 02:17:01.000000', NULL, 1),
(3722108, 523740, 79276, '<td valign="top">Come on, throwing the god-monkey off your back is a happy occasion.  Chin up! Very colorful shot, too.</td>', 'Come on, throwing the god-monkey off your back is a happy occasion.  Chin up! Very colorful shot, too.', '2007-06-01 02:18:21.000000', NULL, 1),
(3722136, 523455, 50034, '<td valign="top">Well illustrated!</td>', 'Well illustrated!', '2007-06-01 02:24:51.000000', NULL, 1),
(3722147, 519549, 50034, '<td valign="top"><b>I''m honored to take that call!</b> <i>What a pleasure it is to be <b>a fisher of men</b> seeking to heal <b>the fissures in men!</b>  :)</i></td>', 'I''m honored to take that call! What a pleasure it is to be a fisher of men seeking to heal the fissures in men!  :)', '2007-06-01 02:27:59.000000', NULL, 1),
(3722173, 522563, 50034, '<td valign="top">Awesome!  :)</td>', 'Awesome!  :)', '2007-06-01 02:32:48.000000', NULL, 1),
(3722182, 523540, 50034, '<td valign="top">Foundational truth!  Thanks for illustrating this!  :)</td>', 'Foundational truth!  Thanks for illustrating this!  :)', '2007-06-01 02:34:10.000000', NULL, 1),
(3722188, 523943, 50034, '<td valign="top">:)</td>', ':)', '2007-06-01 02:35:05.000000', NULL, 1),
(3722196, 519804, 50034, '<td valign="top">"There is one Mediator (i.e. Light) between God &amp; man...Christ Jesus!"  :)</td>', '"There is one Mediator (i.e. Light) between God & man...Christ Jesus!"  :)', '2007-06-01 02:36:51.000000', NULL, 1),
(3722206, 520497, 50034, '<td valign="top">"...and the streets of Heaven are made of gold."  Man''s highest value is God''s road construction material.</td>', '"...and the streets of Heaven are made of gold."  Man''s highest value is God''s road construction material.', '2007-06-01 02:39:01.000000', NULL, 1),
(3722215, 523582, 50034, '<td valign="top">Magnificent!  :)</td>', 'Magnificent!  :)', '2007-06-01 02:40:25.000000', NULL, 1),
(3722232, 523259, 50034, '<td valign="top">Great technicals &amp; colors!  Interesting Incense!</td>', 'Great technicals & colors!  Interesting Incense!', '2007-06-01 02:43:44.000000', NULL, 1),
(3722243, 523798, 50034, '<td valign="top">Beautiful church!  :)</td>', 'Beautiful church!  :)', '2007-06-01 02:46:31.000000', NULL, 1),
(3722252, 519119, 50034, '<td valign="top">small jpeg...check resize function &amp; save for web...preferably PhotoShop Elements...</td>', 'small jpeg...check resize function & save for web...preferably PhotoShop Elements...', '2007-06-01 02:48:41.000000', NULL, 1),
(3722262, 520468, 50034, '<td valign="top">Interesting...You illustrated a Bible verse.  "Don''t get drunk with wine (or whiskey, but be filled with the (Holy) Spirit."  Great photo of the first part of the verse... :)</td>', 'Interesting...You illustrated a Bible verse.  "Don''t get drunk with wine (or whiskey, but be filled with the (Holy) Spirit."  Great photo of the first part of the verse... :)', '2007-06-01 02:53:40.000000', NULL, 1),
(3722269, 523598, 50034, '<td valign="top">Thank You for a beautiful photo &amp; Great illustration!  :)</td>', 'Thank You for a beautiful photo & Great illustration!  :)', '2007-06-01 02:55:45.000000', NULL, 1),
(3722568, 524033, 35352, '<td valign="top">nice detail. I like the desaturated colours. The angel doesn''t quite stand out against the background though.</td>', 'nice detail. I like the desaturated colours. The angel doesn''t quite stand out against the background though.', '2007-06-01 06:21:32.000000', NULL, 1),
(3722685, 522076, 56167, '<td valign="top">would like to have seen more of her face she seems to be a very timid angel, also would have lost the clouds. sorry but it is omo</td>', 'would like to have seen more of her face she seems to be a very timid angel, also would have lost the clouds. sorry but it is omo', '2007-06-01 07:20:20.000000', NULL, 1),
(3722691, 520468, 56167, '<td valign="top">don''t think there is anything holy about this spirit, it has a spirit of its own. would have chosen a different background with so much black on the bottle. omo. good luck</td>', 'don''t think there is anything holy about this spirit, it has a spirit of its own. would have chosen a different background with so much black on the bottle. omo. good luck', '2007-06-01 07:25:42.000000', NULL, 1),
(3722991, 523937, 79104, '<td valign="top">This one made me stop a minute. I love the light shining on the cross even though it is dark.</td>', 'This one made me stop a minute. I love the light shining on the cross even though it is dark.', '2007-06-01 09:08:53.000000', NULL, 1),
(3722992, 524083, 79104, '<td valign="top">Something is missing. Sharpness? Contrast?  Can''t put my finger on it.</td>', 'Something is missing. Sharpness? Contrast?  Can''t put my finger on it.', '2007-06-01 09:09:45.000000', NULL, 1),
(3722996, 524136, 79104, '<td valign="top">The time of worship looks fake. Doesn''t go with the photo. What happened here?</td>', 'The time of worship looks fake. Doesn''t go with the photo. What happened here?', '2007-06-01 09:11:50.000000', NULL, 1),
(3723002, 523994, 79104, '<td valign="top">I am not really sure what this is.</td>', 'I am not really sure what this is.', '2007-06-01 09:14:21.000000', NULL, 1),
(3723009, 522839, 79104, '<td valign="top">Her head and body seem wide. Some sharpness and despeckle might have helped here. I am assuming this is a zoom shot and you were back a ways.</td>', 'Her head and body seem wide. Some sharpness and despeckle might have helped here. I am assuming this is a zoom shot and you were back a ways.', '2007-06-01 09:16:39.000000', NULL, 1),
(3723028, 519763, 79104, '<td valign="top">I believe Jesus was the Messiah and was Jewish/Hebrew. But, not sure the modern day Jewish/Hebrew believe this. Interesting shot. What book is that?</td>', 'I believe Jesus was the Messiah and was Jewish/Hebrew. But, not sure the modern day Jewish/Hebrew believe this. Interesting shot. What book is that?', '2007-06-01 09:20:27.000000', NULL, 1),
(3723033, 521445, 79104, '<td valign="top">Nice. What is at the top?</td>', 'Nice. What is at the top?', '2007-06-01 09:20:52.000000', NULL, 1),
(3723034, 523497, 79104, '<td valign="top">Excellent shot. 9 from me</td>', 'Excellent shot. 9 from me', '2007-06-01 09:21:42.000000', NULL, 1),
(3723055, 522483, 79104, '<td valign="top">Easter? Wasn'' that like two months ago?</td>', 'Easter? Wasn'' that like two months ago?', '2007-06-01 09:29:53.000000', NULL, 1),
(3723105, 523950, 71958, '<td valign="top">nice shot, but i think a stretch for the category</td>', 'nice shot, but i think a stretch for the category', '2007-06-01 09:43:33.000000', NULL, 1),
(3723118, 524147, 71958, '<td valign="top">the sky really washes out the steeple of the church, and the greens in the foreground seem a little flat.</td>', 'the sky really washes out the steeple of the church, and the greens in the foreground seem a little flat.', '2007-06-01 09:45:24.000000', NULL, 1),
(3723241, 523090, 33672, '<td valign="top">Nice shadows. Works well with B&amp;W</td>', 'Nice shadows. Works well with B&W', '2007-06-01 10:14:20.000000', NULL, 1),
(3723595, 523720, 63490, '<td valign="top">This feels like you just went into your church and snapped a picture. A different angle, lighting or crop would have improved this picture.</td>', 'This feels like you just went into your church and snapped a picture. A different angle, lighting or crop would have improved this picture.', '2007-06-01 11:32:10.000000', NULL, 1),
(3723606, 523904, 63490, '<td valign="top">I think this is one of the better religious shots I''ve seen so far. I can''t help but to want to see it as a horizontal instead of vertical so that the two candles on either side is not cut off.</td>', 'I think this is one of the better religious shots I''ve seen so far. I can''t help but to want to see it as a horizontal instead of vertical so that the two candles on either side is not cut off.', '2007-06-01 11:33:47.000000', NULL, 1),
