(3742887, 523827, 9906, '<td valign="top">Your a touch underexposed.  Did you use fill flash?  This is the perfect type of shot for it!<br/>TC</td>', 'Your a touch underexposed.  Did you use fill flash?  This is the perfect type of shot for it!TC', '2007-06-05 18:33:07.000000', NULL, 1),
(3742897, 519107, 9906, '<td valign="top">Your focal point is too far into the frame.  This makes the shot seem awkward with the foreground SO out of focus...<br/>TC</td>', 'Your focal point is too far into the frame.  This makes the shot seem awkward with the foreground SO out of focus...TC', '2007-06-05 18:35:24.000000', NULL, 1),
